insert into public.addon_rules (id, option_a, option_b, reason) values
  ('rule_1', 'neck-off-shoulder', 'sleeves-long', 'Off-shoulder necklines can''t take long sleeves — try puff or sheer sleeves.'),
  ('rule_2', 'neck-off-shoulder', 'sleeves-elbow', 'Off-shoulder necklines can''t take elbow sleeves — try puff or sheer sleeves.'),
  ('rule_3', 'neck-off-shoulder', 'sleeves-cap', 'Off-shoulder already sits on the arm, so cap sleeves aren''t possible.'),
  ('rule_4', 'neck-halter', 'sleeves-cap', 'Halter necklines are sleeveless.'),
  ('rule_5', 'neck-halter', 'sleeves-puff', 'Halter necklines are sleeveless.'),
  ('rule_6', 'neck-halter', 'sleeves-elbow', 'Halter necklines are sleeveless.'),
  ('rule_7', 'neck-halter', 'sleeves-long', 'Halter necklines are sleeveless.'),
  ('rule_8', 'neck-halter', 'sleeves-sheer', 'Halter necklines are sleeveless.'),
  ('rule_9', 'neck-strapless', 'sleeves-cap', 'Strapless bodices can''t hold cap sleeves.'),
  ('rule_10', 'neck-one-shoulder', 'sleeves-puff', 'One-shoulder styles look unbalanced with puff sleeves.'),
  ('rule_11', 'det-cape', 'sleeves-puff', 'A cape sits over the shoulder, so puff sleeves would crush under it.'),
  ('rule_12', 'det-cape', 'det-stole', 'Pick either a cape or a stole.'),
  ('rule_13', 'det-bow', 'waist-belt', 'Choose either a bow or a belt at the waist.'),
  ('rule_14', 'det-bow', 'waist-sash', 'The sash already ties at the waist — choose one.'),
  ('rule_15', 'emb-beadwork', 'emb-sequin', 'Beadwork and sequin scatter compete — choose one.'),
  ('rule_16', 'emb-hand', 'emb-beadwork', 'Choose either hand embroidery or beadwork on the bodice.'),
  ('rule_17', 'len-mini', 'det-overlay', 'A tulle overskirt needs a longer base length.'),
  ('rule_18', 'back-open', 'back-corset', 'An open back can''t also be laced.')
