insert into public.designs (slug, name, category, occasions, description, base_price, fabric_metres, default_fabric, fabric_keys, addon_groups, default_options, featured, badge, id, images, color_images, published, sort) values
  ('blush-leaf-tulle-gown', 'Blush Leaf Tulle Gown', 'bridal', array['Homecoming','Engagement','Party']::text[], 'A strapless satin mini dress with a hand-sculpted leaf appliqué cascading across the bodice, a floor-length tulle overskirt, matching stole and a corset lace-up back.', 24500, 4.5, 'satin', array['satin','silk-blend','crepe']::text[], array['neckline','sleeves','back','lining','embroidery','detail']::text[], array['neck-design','back-corset','lining-full','det-stole']::text[], true, 'Signature', 'des_blush-leaf-tulle-gown', array['/catalog/blush-leaf-tulle-gown/front.webp','/catalog/blush-leaf-tulle-gown/back.webp','/catalog/blush-leaf-tulle-gown/detail.webp','/catalog/blush-leaf-tulle-gown/angle.webp']::text[], '{}'::jsonb, true, 0),
  ('noir-sequin-sash-gown', 'Noir Sequin Sash Gown', 'dress', array['Party','Wedding']::text[], 'A fitted V-neck sequin gown on fine straps with a satin waistband and a sweeping side drape that becomes a train at the back. Lace-up corset back.', 32000, 4, 'sequin-net', array['sequin-net','satin','crepe']::text[], array['neckline','sleeves','length','back','lining','embroidery']::text[], array['neck-design','len-design','back-corset','lining-full']::text[], true, 'New', 'des_noir-sequin-sash-gown', array['/catalog/noir-sequin-sash-gown/front.webp','/catalog/noir-sequin-sash-gown/back.webp','/catalog/noir-sequin-sash-gown/detail.webp','/catalog/noir-sequin-sash-gown/angle.webp']::text[], '{}'::jsonb, true, 1),
  ('mauve-lace-drape-saree', 'Mauve Lace Pre-Draped Saree', 'saree-blouse', array['Wedding','Engagement','Festival']::text[], 'A ready-to-wear saree: satin flared skirt and sleeveless V-neck blouse with a floral lace drape stitched in place. No pleating, no pins.', 38500, 6, 'satin', array['satin','silk-blend','crepe']::text[], array['neckline','sleeves','back','lining','embroidery']::text[], array['neck-design','back-zip','lining-full']::text[], true, null, 'des_mauve-lace-drape-saree', array['/catalog/mauve-lace-drape-saree/front.webp','/catalog/mauve-lace-drape-saree/back.webp','/catalog/mauve-lace-drape-saree/detail.webp','/catalog/mauve-lace-drape-saree/angle.webp']::text[], '{}'::jsonb, true, 2),
  ('maroon-tie-back-column-dress', 'Maroon Tie-Back Column Dress', 'dress', array['Party','Homecoming']::text[], 'A sleek ankle-length column dress with a soft sweetheart neckline, fine straps that cross into long ties and a dramatic open back.', 14500, 3, 'jersey', array['jersey','crepe','satin']::text[], array['neckline','length','back','lining','embroidery','detail','pockets']::text[], array['neck-design','len-design','back-open','lining-half']::text[], true, null, 'des_maroon-tie-back-column-dress', array['/catalog/maroon-tie-back-column-dress/front.webp','/catalog/maroon-tie-back-column-dress/back.webp','/catalog/maroon-tie-back-column-dress/detail.webp','/catalog/maroon-tie-back-column-dress/angle.webp']::text[], '{}'::jsonb, true, 3),
  ('sage-bloom-lehenga-set', 'Sage Bloom Lehenga Set', 'bridal', array['Wedding','Engagement','Festival']::text[], 'A V-neck crop blouse and flared tulle lehenga skirt covered in hand-placed 3D fabric flowers with beaded vines.', 58000, 7, 'tulle', array['tulle','satin','silk-blend']::text[], array['neckline','sleeves','back','lining','embroidery','detail']::text[], array['neck-design','back-zip','lining-full']::text[], true, 'Bridal', 'des_sage-bloom-lehenga-set', array['/catalog/sage-bloom-lehenga-set/front.webp','/catalog/sage-bloom-lehenga-set/back.webp','/catalog/sage-bloom-lehenga-set/detail.webp','/catalog/sage-bloom-lehenga-set/angle.webp']::text[], '{}'::jsonb, true, 4),
  ('aqua-one-shoulder-cape-gown', 'Aqua One-Shoulder Cape Gown', 'dress', array['Wedding','Party','Engagement']::text[], 'A one-shoulder satin mermaid gown with a beaded bodice, a sheer beaded lace front panel and a floor-sweeping tulle cape.', 42000, 5, 'satin', array['satin','silk-blend','crepe']::text[], array['neckline','length','back','lining','embroidery','detail']::text[], array['neck-design','len-design','back-zip','lining-full']::text[], true, null, 'des_aqua-one-shoulder-cape-gown', array['/catalog/aqua-one-shoulder-cape-gown/front.webp','/catalog/aqua-one-shoulder-cape-gown/back.webp','/catalog/aqua-one-shoulder-cape-gown/detail.webp','/catalog/aqua-one-shoulder-cape-gown/angle.webp']::text[], '{}'::jsonb, true, 5),
  ('cocoa-tiered-maxi-skirt-set', 'Cocoa Tiered Maxi Skirt Set', 'sets', array['Casual','Office']::text[], 'A three-tier gathered maxi skirt with pockets, a fitted knit tank and a chunky hand-made cardigan. Easy, warm and made to last.', 12500, 3.5, 'linen', array['linen','cotton']::text[], array['length','lining','embroidery','pockets']::text[], array['len-design','lining-none','pockets-side']::text[], true, null, 'des_cocoa-tiered-maxi-skirt-set', array['/catalog/cocoa-tiered-maxi-skirt-set/front.webp','/catalog/cocoa-tiered-maxi-skirt-set/back.webp','/catalog/cocoa-tiered-maxi-skirt-set/detail.webp','/catalog/cocoa-tiered-maxi-skirt-set/angle.webp']::text[], '{}'::jsonb, true, 6),
  ('little-mal-puff-sleeve-frock', 'Little Mal Puff-Sleeve Frock', 'kids', array['Kids','Party','Festival']::text[], 'A twirly cotton frock with puff sleeves and a waist bow. Sized for ages 2–12.', 7500, 1.8, 'cotton', array['cotton','linen','satin','tulle']::text[], array['neckline','sleeves','length','embroidery','detail','pockets','buttons']::text[], array['neck-design','sleeves-puff','len-design','det-bow']::text[], false, 'Kids', 'des_little-mal-puff-sleeve-frock', '{}'::text[], '{}'::jsonb, false, 7),
  ('mal-crochet-crop-top', 'Mal Crochet Crop Top', 'crochet-top', array['Casual','Festival']::text[], 'A hand-crocheted square-neck crop top with flower-motif straps, made by our designer in cotton yarn.', 6500, 0.8, 'crochet-cotton', array['crochet-cotton']::text[], array['sleeves','detail','buttons']::text[], array['sleeves-none']::text[], true, 'Handmade', 'des_mal-crochet-crop-top', '{}'::text[], '{}'::jsonb, false, 8),
  ('classic-sweetheart-saree-blouse', 'Classic Sweetheart Saree Blouse', 'saree-blouse', array['Wedding','Festival','Office']::text[], 'A tailored sweetheart saree blouse with elbow sleeves and a gold trim. Bring your saree, we''ll match it.', 5500, 1, 'silk-blend', array['silk-blend','brocade','satin','cotton']::text[], array['neckline','sleeves','back','embroidery','buttons']::text[], array['neck-design','sleeves-elbow','back-buttons']::text[], false, null, 'des_classic-sweetheart-saree-blouse', '{}'::text[], '{}'::jsonb, false, 9),
  ('everyday-aline-cotton-frock', 'Everyday A-Line Cotton Frock', 'frock', array['Casual','Office']::text[], 'Our everyday frock: boat neck, cap sleeves, a self belt and an easy A-line midi skirt with pockets.', 8900, 2.8, 'cotton', array['cotton','linen','crepe']::text[], array['neckline','sleeves','length','back','waist','lining','embroidery','buttons','detail','pockets']::text[], array['neck-design','sleeves-cap','len-design','waist-belt','pockets-side']::text[], false, null, 'des_everyday-aline-cotton-frock', '{}'::text[], '{}'::jsonb, false, 10),
  ('navy-sequin-fan-party-dress', 'Navy Sequin Fan Party Dress', 'dress', array['Party','Homecoming']::text[], 'A knee-length satin fit-and-flare dress with an asymmetric neckline and a bodice of hand-sewn sequin rays fanning out from the waist. Gathered full skirt, concealed back zip.', 18500, 3.5, 'satin', array['satin','silk-blend','crepe']::text[], array['neckline','sleeves','length','back','lining','embroidery','detail','pockets']::text[], array['neck-design','len-design','back-zip','lining-full']::text[], true, 'New', 'des_navy-sequin-fan-party-dress', array['/catalog/navy-sequin-fan-party-dress/front.webp','/catalog/navy-sequin-fan-party-dress/back.webp','/catalog/navy-sequin-fan-party-dress/detail.webp','/catalog/navy-sequin-fan-party-dress/angle.webp']::text[], '{}'::jsonb, true, 11),
  ('navy-silver-peplum-drape-saree', 'Navy Silver Peplum Drape Saree', 'saree-blouse', array['Wedding','Engagement','Party']::text[], 'A pre-draped saree with a peplum front drape and silver-trimmed pallu over a column skirt embroidered with flowing silver vines. V-neck blouse with sheer puff sleeves and embroidered cuffs.', 42000, 6, 'crepe', array['crepe','silk-blend','satin']::text[], array['neckline','sleeves','back','lining','embroidery','detail']::text[], array['neck-design','sleeves-puff','back-zip','lining-full']::text[], true, 'New', 'des_navy-silver-peplum-drape-saree', array['/catalog/navy-silver-peplum-drape-saree/front.webp','/catalog/navy-silver-peplum-drape-saree/back.webp','/catalog/navy-silver-peplum-drape-saree/detail.webp','/catalog/navy-silver-peplum-drape-saree/angle.webp']::text[], '{}'::jsonb, true, 12),
  ('champagne-lace-high-neck-saree', 'Champagne Lace High-Neck Saree', 'bridal', array['Wedding','Engagement']::text[], 'A soft net saree covered in gold-thread floral embroidery with a scalloped lace border, worn with a sleeveless high-neck sheer lace blouse.', 46000, 6.5, 'tulle', array['tulle','silk-blend','satin']::text[], array['neckline','sleeves','back','lining','embroidery','buttons']::text[], array['neck-design','sleeves-none','back-buttons','lining-half']::text[], true, 'Bridal', 'des_champagne-lace-high-neck-saree', array['/catalog/champagne-lace-high-neck-saree/front.webp','/catalog/champagne-lace-high-neck-saree/back.webp','/catalog/champagne-lace-high-neck-saree/detail.webp','/catalog/champagne-lace-high-neck-saree/angle.webp']::text[], '{}'::jsonb, true, 13),
  ('cocoa-linen-peplum-top', 'Cocoa Linen Peplum Top', 'sets', array['Office','Casual']::text[], 'A sleeveless boat-neck linen top with a fitted bodice and a box-pleated peplum. Back zip. Lovely with wide-leg trousers — ask us to make a matching pair.', 6900, 1.4, 'linen', array['linen','cotton','crepe']::text[], array['neckline','sleeves','lining','embroidery','buttons']::text[], array['neck-design','sleeves-none','lining-none']::text[], false, null, 'des_cocoa-linen-peplum-top', array['/catalog/cocoa-linen-peplum-top/front.webp','/catalog/cocoa-linen-peplum-top/back.webp','/catalog/cocoa-linen-peplum-top/detail.webp','/catalog/cocoa-linen-peplum-top/angle.webp']::text[], '{}'::jsonb, true, 14),
  ('botanical-bow-shoulder-mini', 'Botanical Bow-Shoulder Mini', 'dress', array['Casual','Party']::text[], 'A one-shoulder A-line mini in botanical-print linen with a long tie that knots into a bow at the open shoulder.', 9800, 2, 'linen', array['linen','cotton']::text[], array['length','lining','embroidery','detail','pockets']::text[], array['len-design','lining-half']::text[], true, null, 'des_botanical-bow-shoulder-mini', array['/catalog/botanical-bow-shoulder-mini/front.webp','/catalog/botanical-bow-shoulder-mini/back.webp','/catalog/botanical-bow-shoulder-mini/detail.webp','/catalog/botanical-bow-shoulder-mini/angle.webp']::text[], '{}'::jsonb, true, 15),
  ('lilac-ruffle-saree', 'Lilac Ruffle Saree', 'saree-blouse', array['Wedding','Festival','Office']::text[], 'A soft textured saree edged with frills along the pallu and hem, paired with a long-sleeve sheer lace blouse in a deeper lilac.', 28500, 6, 'cotton', array['cotton','crepe','silk-blend']::text[], array['neckline','sleeves','back','lining','embroidery']::text[], array['neck-design','sleeves-long','back-zip','lining-half']::text[], false, null, 'des_lilac-ruffle-saree', array['/catalog/lilac-ruffle-saree/front.webp','/catalog/lilac-ruffle-saree/back.webp','/catalog/lilac-ruffle-saree/detail.webp','/catalog/lilac-ruffle-saree/angle.webp']::text[], '{}'::jsonb, true, 16)
